//! innoframework-rpc: typed RPC routes with compile-time auth guard enforcement.
//!
//! Implements ADR-14 (proc-macro typestate) and TR-1.3 (a route without a
//! guard fails to compile).
//!
//! Typestate:
//! - `RpcRoute: Guarded` — only route structs generated by the
//!   `#[rpc(guard = ...)]` proc-macro can implement this.
//! - Unguarded routes are unrepresentable: they cannot implement `Guarded`,
//!   so they cannot implement `RpcRoute` or be registered.

#![allow(async_fn_in_trait)]

/// Re-exported so proc-macro-generated code can reference the error type
/// through a single crate path.
pub use innoframework_core::AuthError;

/// Marker trait: implemented only by route structs that declared a guard.
pub trait Guarded {}

/// Typed RPC route. Only `T: Guarded` can implement this, because only the
/// proc-macro can implement `Guarded`, and it requires a `guard` argument.
pub trait RpcRoute: Guarded {
    /// Handle the request. Returns `AuthError` if the guard fails.
    async fn handle(&self) -> Result<(), AuthError>;
}

/// Compile-time registration guard: only `T: Guarded + RpcRoute` may be registered.
pub fn register_route<T: Guarded + RpcRoute>(_route: &T) {
    // Registration is a no-op at the type level; the guard requirement is
    // enforced by the `T: Guarded` bound.
}
